#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <tuple>
using namespace std;

using i64 = long long;
using pii = pair<int, int>;

constexpr int DX[] = {0, 0, -1, 1};
constexpr int DY[] = {-1, 1, 0, 0};

struct edge {
    int from;
    int to;
    i64 cap;
    i64 flow;
    edge(int f, int t, i64 c) : from(f), to(t), cap(c), flow(0) {}
};

struct dinic {
    const i64 INF = 1e18;
    int n;
    int src;
    int dst;
    vector<edge> e;
    vector<vector<int>> g;
    vector<int> lvl;
    vector<int> ptr;
    queue<int> q;

    dinic(int nodes, int s, int t)
        : n(nodes), src(s), dst(t) {
        g.resize(n);
        lvl.resize(n);
        ptr.resize(n);
    }

    void link(int u, int v, i64 c) {
        e.emplace_back(u, v, c);
        e.emplace_back(v, u, 0);
        g[u].push_back((int)e.size() - 2);
        g[v].push_back((int)e.size() - 1);
    }

    bool bfs_layer() {
        fill(lvl.begin(), lvl.end(), -1);
        lvl[src] = 0;
        q.push(src);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int id : g[u]) {
                auto& ed = e[id];
                if (ed.cap - ed.flow > 0 && lvl[ed.to] == -1) {
                    lvl[ed.to] = lvl[u] + 1;
                    q.push(ed.to);
                }
            }
        }
        return lvl[dst] != -1;
    }

    i64 dfs_push(int u, i64 flow) {
        if (u == dst) return flow;
        for (int& i = ptr[u]; i < (int)g[u].size(); ++i) {
            int id = g[u][i];
            auto& ed = e[id];
            if (lvl[ed.to] == lvl[u] + 1 && ed.cap - ed.flow > 0) {
                i64 pushed = dfs_push(ed.to, min(flow, ed.cap - ed.flow));
                if (pushed > 0) {
                    ed.flow += pushed;
                    e[id ^ 1].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    i64 ford_fulkerson() {
        i64 total = 0;
        while (bfs_layer()) {
            fill(ptr.begin(), ptr.end(), 0);
            i64 pushed;
            while ((pushed = dfs_push(src, INF)) > 0)
                total += pushed;
        }
        return total;
    }
};

int n, T;
string gridA[15];
string gridB[15];
int distGrid[15][15];

bool safe(int r, int c) {
    return r >= 0 && c >= 0 && r < n && c < n && gridA[r][c] != 'Y' && gridA[r][c] != 'Z';
}

void flood_fill(int sx, int sy) {
    memset(distGrid, -1, sizeof(distGrid));
    queue<pii> qu;
    qu.emplace(sx, sy);
    distGrid[sx][sy] = 0;
    while (!qu.empty()) {
        auto [x, y] = qu.front(); qu.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + DX[d], ny = y + DY[d];
            if (safe(nx, ny) && distGrid[nx][ny] == -1) {
                distGrid[nx][ny] = distGrid[x][y] + 1;
                qu.emplace(nx, ny);
            }
        }
    }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (distGrid[i][j] == -1) distGrid[i][j] = 1000000000;
}

int memo_table[65][12][12][12][12];
int memo_flag[65][12][12][12][12];

bool can_attain(int curTime, int fromX, int fromY, int toX, int toY) {
    if (distGrid[fromX][fromY] < curTime) return false;
    if (fromX == toX && fromY == toY) return true;
    if (curTime >= T) return false;
    if (distGrid[fromX][fromY] <= curTime) return false;
    if (memo_flag[curTime][fromX][fromY][toX][toY]) return memo_table[curTime][fromX][fromY][toX][toY];
    memo_flag[curTime][fromX][fromY][toX][toY] = true;
    for (int d = 0; d < 4; ++d) {
        int nx = fromX + DX[d], ny = fromY + DY[d];
        if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
        if (gridA[nx][ny] == 'Y' || gridA[nx][ny] == 'Z') continue;
        if (can_attain(curTime + 1, nx, ny, toX, toY)) {
            memo_table[curTime][fromX][fromY][toX][toY] = 1;
            return true;
        }
    }
    memo_table[curTime][fromX][fromY][toX][toY] = 0;
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    memset(memo_table, -1, sizeof(memo_table));
    cin >> n >> T;
    for (int i = 0; i < n; ++i) cin >> gridA[i];
    for (int i = 0; i < n; ++i) cin >> gridB[i];

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (gridA[i][j] == 'Z') {
                flood_fill(i, j);
                goto skip_to_z;
            }
        }
    }
    skip_to_z:;

    vector<pii> sourcePoints, sinkPoints;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (gridA[i][j] != 'Z' && gridA[i][j] != 'Y' && gridA[i][j] != '0')
                sourcePoints.emplace_back(i, j);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (gridB[i][j] != 'Z' && gridB[i][j] != 'Y' && gridB[i][j] != '0')
                sinkPoints.emplace_back(i, j);

    int M = sourcePoints.size() + sinkPoints.size() + 2;
    dinic flow(M, 0, M - 1);

    for (int i = 0; i < sourcePoints.size(); ++i) {
        i64 capacity = gridA[sourcePoints[i].first][sourcePoints[i].second] - '0';
        flow.link(0, i + 1, capacity);
    }
    for (int i = 0; i < sinkPoints.size(); ++i) {
        i64 capacity = gridB[sinkPoints[i].first][sinkPoints[i].second] - '0';
        flow.link(sourcePoints.size() + 1 + i, M - 1, capacity);
    }

    for (int i = 0; i < sourcePoints.size(); ++i)
        for (int j = 0; j < sinkPoints.size(); ++j)
            if (can_attain(0, sourcePoints[i].first, sourcePoints[i].second, sinkPoints[j].first, sinkPoints[j].second))
                flow.link(i + 1, sourcePoints.size() + 1 + j, 10000000LL);

    cout << flow.ford_fulkerson() << '\n';
    return 0;
}
